{"content":"#!/usr/bin/env python3
"""UCI chess engine. Negamax + alpha-beta + quiescence + iterative deepening."""
import sys
import time
import chess

MATE = 100000
INF = 10 ** 9

PIECE_VAL = {
    chess.PAWN: 100,
    chess.KNIGHT: 320,
    chess.BISHOP: 330,
    chess.ROOK: 500,
    chess.QUEEN: 900,
    chess.KING: 0,
}

# Piece-square tables (from White's perspective, a1=0 ... h8=63)
PAWN_T = [
    0, 0, 0, 0, 0, 0, 0, 0,
    50, 50, 50, 50, 50, 50, 50, 50,
    10, 10, 20, 30, 30, 20, 10, 10,
    5, 5, 10, 25, 25, 10, 5, 5,
    0, 0, 0, 20, 20, 0, 0, 0,
    5, -5, -10, 0, 0, -10, -5, 5,
    5, 10, 10, -20, -20, 10, 10, 5,
    0, 0, 0, 0, 0, 0, 0, 0,
]
KNIGHT_T = [
    -50, -40, -30, -30, -30, -30, -40, -50,
    -40, -20, 0, 0, 0, 0, -20, -40,
    -30, 0, 10, 15, 15, 10, 0, -30,
    -30, 5, 15, 20, 20, 15, 5, -30,
    -30, 0, 15, 20, 20, 15, 0, -30,
    -30, 5, 10, 15, 15, 10, 5, -30,
    -40, -20, 0, 5, 5, 0, -20, -40,
    -50, -40, -30, -30, -30, -30, -40, -50,
]
BISHOP_T = [
    -20, -10, -10, -10, -10, -10, -10, -20,
    -10, 0, 0, 0, 0, 0, 0, -10,
    -10, 0, 5, 10, 10, 5, 0, -10,
    -10, 5, 5, 10, 10, 5, 5, -10,
    -10, 0, 10, 10, 10, 10, 0, -10,
    -10, 10, 10, 10, 10, 10, 10, -10,
    -10, 5, 0, 0, 0, 0, 5, -10,
    -20, -10, -10, -10, -10, -10, -10, -20,
]
ROOK_T = [
    0, 0, 0, 0, 0, 0, 0, 0,
    5, 10, 10, 10, 10, 10, 10, 5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    -5, 0, 0, 0, 0, 0, 0, -5,
    0, 0, 0, 5, 5, 0, 0, 0,
]
QUEEN_T = [
    -20, -10, -10, -5, -5, -10, -10, -20,
    -10, 0, 0, 0, 0, 0, 0, -10,
    -10, 0, 5, 5, 5, 5, 0, -10,
    -5, 0, 5, 5, 5, 5, 0, -5,
    0, 0, 5, 5, 5, 5, 0, -5,
    -10, 5, 5, 5, 5, 5, 0, -10,
    -10, 0, 5, 0, 0, 0, 0, -10,
    -20, -10, -10, -5, -5, -10, -10, -20,
]
KING_MID_T = [
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -30, -40, -40, -50, -50, -40, -40, -30,
    -20, -30, -30, -40, -40, -30, -30, -20,
    -10, -20, -20, -20, -20, -20, -20, -10,
    20, 20, 0, 0, 0, 0, 20, 20,
    20, 30, 10, 0, 0, 10, 30, 20,
]
KING_END_T = [
    -50, -40, -30, -20, -20, -30, -40, -50,
    -30, -20, -10, 0, 0, -10, -20, -30,
    -30, -10, 20, 30, 30, 20, -10, -30,
    -30, -10, 30, 40, 40, 30, -10, -30,
    -30, -10, 30, 40, 40, 30, -10, -30,
    -30, -10, 20, 30, 30, 20, -10, -30,
    -30, -30, 0, 0, 0, 0, -30, -30,
    -50, -30, -30, -30, -30, -30, -30, -50,
]

PST = {
    chess.PAWN: PAWN_T,
    chess.KNIGHT: KNIGHT_T,
    chess.BISHOP: BISHOP_T,
    chess.ROOK: ROOK_T,
    chess.QUEEN: QUEEN_T,
}

CENTER = (chess.D4, chess.D5, chess.E4, chess.E5)
EXT_CENTER = (chess.C3, chess.C4, chess.C5, chess.C6, chess.D3, chess.D6,
              chess.E3, chess.E6, chess.F3, chess.F4, chess.F5, chess.F6)


class SearchTimeout(Exception):
    pass


class Engine:
    def __init__(self):
        self.board = chess.Board()
        self.nodes = 0
        self.deadline = 0.0
        self.tt = {}

    # ---------- evaluation (from side-to-move perspective) ----------
    def evaluate(self, board):
        if board.is_checkmate():
            # side to move is mated
            return -MATE
        if board.is_stalemate() or board.is_insufficient_material():
            return 0
        score_w = 0  # white perspective
        piece_map = board.piece_map()
        # endgame detection: queens off or low material (excluding kings/pawns)
        non_pawn_mat = 0
        for sq, p in piece_map.items():
            if p.piece_type not in (chess.PAWN, chess.KING):
                non_pawn_mat += PIECE_VAL[p.piece_type]
        endgame = non_pawn_mat <= 1300  # e.g. rook+minor or less per side-ish

        for sq, p in piece_map.items():
            v = PIECE_VAL[p.piece_type]
            if p.piece_type == chess.KING:
                table = KING_END_T if endgame else KING_MID_T
                b = table[sq if p.color == chess.WHITE else chess.square_mirror(sq)]
            elif p.piece_type in PST:
                table = PST[p.piece_type]
                b = table[sq if p.color == chess.WHITE else chess.square_mirror(sq)]
            else:
                b = 0
            if p.color == chess.WHITE:
                score_w += v + b
            else:
                score_w -= v + b

        # center control
        for sq in CENTER:
            p = board.piece_at(sq)
            if p:
                score_w += 12 if p.color == chess.WHITE else -12
        for sq in EXT_CENTER:
            p = board.piece_at(sq)
            if p:
                score_w += 5 if p.color == chess.WHITE else -5

        # bishop pair
        w_b = sum(1 for s, p in piece_map.items()
                  if p.color == chess.WHITE and p.piece_type == chess.BISHOP)
        b_b = sum(1 for s, p in piece_map.items()
                  if p.color == chess.BLACK and p.piece_type == chess.BISHOP)
        if w_b >= 2:
            score_w += 30
        if b_b >= 2:
            score_w -= 30

        # mobility (cheap: count only, capped cost)
        # mobility is expensive; approximate with piece count independent term skipped;
        # instead reward side not in check handled by search.
        if board.is_check():
            # side to move is in check -> bad for them
            score_w += -25 if board.turn == chess.WHITE else 25

        # passed pawns bonus
        for sq, p in piece_map.items():
            if p.piece_type == chess.PAWN:
                if self._is_passed(board, sq, p.color):
                    adv = chess.square_rank(sq) if p.color == chess.WHITE else 7 - chess.square_rank(sq)
                    bonus = 10 + adv * adv * 2
                    score_w += bonus if p.color == chess.WHITE else -bonus

        # encourage castling / king safety: penalize king stuck in center mid-game
        if not endgame:
            wk = board.king(chess.WHITE)
            bk = board.king(chess.BLACK)
            if wk is not None and chess.square_rank(wk) == 0 and chess.square_file(wk) in (3, 4):
                score_w -= 15
            if bk is not None and chess.square_rank(bk) == 7 and chess.square_file(bk) in (3, 4):
                score_w += 15

        return score_w if board.turn == chess.WHITE else -score_w

    @staticmethod
    def _is_passed(board, sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf <= 7:
                if color == chess.WHITE:
                    for nr in range(r + 1, 8):
                        p = board.piece_at(chess.square(nf, nr))
                        if p and p.piece_type == chess.PAWN and p.color == chess.BLACK:
                            return False
                else:
                    for nr in range(r - 1, -1, -1):
                        p = board.piece_at(chess.square(nf, nr))
                        if p and p.piece_type == chess.PAWN and p.color == chess.WHITE:
                            return False
        return True

    # ---------- move ordering ----------
    def ordered_moves(self, board, tt_move=None):
        moves = list(board.legal_moves)
        scored = []
        for m in moves:
            s = 0
            if tt_move is not None and m == tt_move:
                s = 10_000_000
            else:
                cap = board.piece_at(m.to_square)
                if board.is_en_passant(m):
                    s = 100000 + 100 - (PIECE_VAL[board.piece_at(m.from_square).piece_type] // 10)
                elif cap:
                    attacker = board.piece_at(m.from_square)
                    s = 100000 + (PIECE_VAL[cap.piece_type] * 10 - PIECE_VAL[attacker.piece_type])
                if m.promotion:
                    s += 90000 + (PIECE_VAL[m.promotion] if m.promotion in PIECE_VAL else 0)
                if board.is_castling(m):
                    s += 5000
                # checks first-ish: giving check is often good
                board.push(m)
                if board.is_check():
                    s += 3000
                board.pop()
                # centralize: bonus for moving toward center
                to_f, to_r = chess.square_file(m.to_square), chess.square_rank(m.to_square)
                s += (3 - abs(3.5 - to_f)) * 4 + (3 - abs(3.5 - to_r)) * 4
            scored.append((s, m))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [m for _, m in scored]

    def quiescence(self, board, alpha, beta, depth):
        self.nodes += 1
        if self.nodes & 1023 == 0 and time.monotonic() > self.deadline:
            raise SearchTimeout()
        if board.is_checkmate():
            return -MATE
        if board.is_stalemate() or board.is_insufficient_material():
            return 0
        stand = self.evaluate(board)
        if stand >= beta:
            return beta
        if stand > alpha:
            alpha = stand
        if depth <= 0:
            return alpha
        # captures, promotions, and checks evasions: if in check, consider all moves
        if board.is_check():
            moves = self.ordered_moves(board)
        else:
            moves = [m for m in self.ordered_moves(board)
                     if board.is_capture(m) or m.promotion or board.is_en_passant(m)]
        for m in moves:
            board.push(m)
            score = -self.quiescence(board, -beta, -alpha, depth - 1)
            board.pop()
            if score >= beta:
                return beta
            if score > alpha:
                alpha = score
        return alpha

    def negamax(self, board, depth, alpha, beta, ply):
        self.nodes += 1
        if self.nodes & 1023 == 0 and time.monotonic() > self.deadline:
            raise SearchTimeout()
        if board.is_checkmate():
            return -MATE + ply
        if board.is_stalemate() or board.is_insufficient_material():
            return 0
        if board.can_claim_threefold_repetition():
            return 0
        if board.halfmove_clock >= 100:
            return 0
        if depth <= 0:
            return self.quiescence(board, alpha, beta, 4)

        key = (board._transposition_key(), depth)
        tt_move = self.tt.get(key)
        moves = self.ordered_moves(board, tt_move)
        best = -INF
        best_move = moves[0] if moves else None
        for m in moves:
            board.push(m)
            score = -self.negamax(board, depth - 1, -beta, -alpha, ply + 1)
            board.pop()
            if score > best:
                best = score
                best_move = m
            if best > alpha:
                alpha = best
            if alpha >= beta:
                break
        if best_move is not None:
            self.tt[key] = best_move
        return best

    def search(self, board, max_depth, time_limit):
        self.deadline = time.monotonic() + time_limit
        self.nodes = 0
        self.tt = {}
        moves = self.ordered_moves(board)
        if not moves:
            return None
        if len(moves) == 1:
            return moves[0]
        # quick immediate-mate check (also ensures mate-in-1 edge test)
        for m in moves:
            board.push(m)
            if board.is_checkmate():
                board.pop()
                return m
            board.pop()
        best = moves[0]
        try:
            for depth in range(1, max_depth + 1):
                alpha = -INF
                beta = INF
                local_best = best
                local_best_score = -INF
                # search moves ordered with current best first
                ordered = [best] + [m for m in self.ordered_moves(board) if m != best]
                for m in ordered:
                    board.push(m)
                    score = -self.negamax(board, depth - 1, -beta, -alpha, 1)
                    board.pop()
                    if time.monotonic() > self.deadline:
                        raise SearchTimeout()
                    if score > local_best_score:
                        local_best_score = score
                        local_best = m
                    if score > alpha:
                        alpha = score
                best = local_best
                # don't waste time if we found mate
                if local_best_score > MATE - 1000:
                    break
                if time.monotonic() > self.deadline:
                    break
        except SearchTimeout:
            pass
        return best


def parse_position(line, board):
    # line forms:
    #   position startpos [moves ...]
    #   position fen <fen> [moves ...]
    rest = line[len("position"):].strip()
    moves = []
    if rest.startswith("startpos"):
        board.reset()
        rest = rest[len("startpos"):].strip()
        if rest.startswith("moves"):
            moves = rest[len("moves"):].strip().split()
    elif rest.startswith("fen"):
        rest = rest[len("fen"):].strip()
        # split off trailing " moves ..."
        if " moves " in f" {rest} " or rest.endswith(" moves") or " moves" in rest:
            # find " moves " token boundary
            idx = rest.find(" moves")
            # ensure it's a standalone token (" moves " or end)
            fen_part = rest[:idx].strip()
            moves_part = rest[idx:].strip()
            if moves_part.startswith("moves"):
                moves = moves_part[len("moves"):].strip().split()
            rest = fen_part
        board.set_fen(rest)
    else:
        return
    for ms in moves:
        try:
            board.push_uci(ms)
        except ValueError:
            break


def main():
    engine = Engine()
    board = engine.board
    data = sys.stdin.read().splitlines()
    out = sys.stdout
    for raw in data:
        line = raw.strip()
        if not line:
            continue
        if line == "uci":
            out.write("id name MyEngine\nid author Muse\nuciok\n")
            out.flush()
        elif line == "isready":
            out.write("readyok\n")
            out.flush()
        elif line.startswith("position"):
            try:
                parse_position(line, board)
            except ValueError:
                # illegal FEN: fall back to startpos rather than crashing
                board.reset()
        elif line.startswith("go"):
            legal = list(board.legal_moves)
            if not legal:
                out.write("bestmove 0000\n")
                out.flush()
                continue
            # time budget: leave headroom under the 2s harness timeout
            n_pieces = len(board.piece_map())
            if n_pieces <= 6:
                max_depth, budget = 6, 1.2
            elif n_pieces <= 12:
                max_depth, budget = 4, 1.3
            else:
                max_depth, budget = 3, 1.35
            try:
                mv = engine.search(board, max_depth, budget)
            except Exception:
                mv = engine.ordered_moves(board)[0] if legal else None
            if mv is None:
                mv = legal[0]
            out.write(f"bestmove {mv.uci()}\n")
            out.flush()
        elif line == "ucinewgame":
            engine.tt = {}
        elif line in ("quit", "stop"):
            break
    out.flush()


if __name__ == "__main__":
    main()
